import requests

BASE_URL = "https://api.themoviedb.org/3"
API_KEY = "YOUR_API_KEY"

def search_person(name):
    response = requests.get(
        f"{BASE_URL}/search/person",
        params={"api_key": API_KEY, "query": name},
    )
    response.raise_for_status()
    return response.json().get("results", [])

def get_credits(person_id):
    response = requests.get(
        f"{BASE_URL}/person/{person_id}/tv_credits",
        params={"api_key": API_KEY},
    )
    response.raise_for_status()
    return response.json()

yui_results = search_person("Yui Aragaki")
gen_results = search_person("Gen Hoshino")

if yui_results and gen_results:
    yui_id = yui_results[0]["id"]
    gen_id = gen_results[0]["id"]

    yui_credits = get_credits(yui_id)
    gen_credits = get_credits(gen_id)

    yui_shows = {
        show.get("id"): show
        for category in ("cast", "crew")
        for show in yui_credits.get(category, [])
        if show.get("id") is not None
    }
    gen_show_ids = {
        show.get("id")
        for category in ("cast", "crew")
        for show in gen_credits.get(category, [])
    }

    matches = [
        show for show_id, show in yui_shows.items()
        if show_id in gen_show_ids
        and "married" in show.get("name", "").lower()
        and "job" in show.get("name", "").lower()
    ]

    print(bool(matches))
else:
    print(False)
